// Description: C header of the sdio_host register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-12
#ifndef SDIO_HOST_REGS_H
#define SDIO_HOST_REGS_H
#define SDIO_HOST_REGS_ID_OFFSET 0x00u
#define SDIO_HOST_REGS_VERSION_OFFSET 0x04u
#define SDIO_HOST_REGS_DATE_OFFSET 0x08u
#define SDIO_HOST_REGS_ID_VALUE 0x5344494Fu   /* "SDIO" */
#define SDIO_HOST_REGS_CMD_OFFSET 0x10u   /* RW */
#define SDIO_HOST_REGS_CMD_RESET 0x00000000u
#define SDIO_HOST_REGS_CMD_INDEX_SHIFT 0u
#define SDIO_HOST_REGS_CMD_INDEX_MASK 0x0000003Fu
#define SDIO_HOST_REGS_CMD_RESP_SHIFT 6u
#define SDIO_HOST_REGS_CMD_RESP_MASK 0x000000C0u
#define SDIO_HOST_REGS_CMD_DIR_SHIFT 8u
#define SDIO_HOST_REGS_CMD_DIR_MASK 0x00000300u
#define SDIO_HOST_REGS_CMD_NO_CRC_SHIFT 10u
#define SDIO_HOST_REGS_CMD_NO_CRC_MASK 0x00000400u
#define SDIO_HOST_REGS_ARG_OFFSET 0x14u   /* RW */
#define SDIO_HOST_REGS_ARG_RESET 0x00000000u
#define SDIO_HOST_REGS_RESP_OFFSET 0x18u   /* RO array, stride 4 */
#define SDIO_HOST_REGS_RESP_STRIDE 4u
#define SDIO_HOST_REGS_RESP_RESET 0x00000000u
#define SDIO_HOST_REGS_STATUS_OFFSET 0x28u   /* CMD */
#define SDIO_HOST_REGS_STATUS_RESET 0x00000000u
#define SDIO_HOST_REGS_STATUS_BUSY_SHIFT 0u
#define SDIO_HOST_REGS_STATUS_BUSY_MASK 0x00000001u
#define SDIO_HOST_REGS_STATUS_CMD_DONE_SHIFT 1u
#define SDIO_HOST_REGS_STATUS_CMD_DONE_MASK 0x00000002u
#define SDIO_HOST_REGS_STATUS_DAT_DONE_SHIFT 2u
#define SDIO_HOST_REGS_STATUS_DAT_DONE_MASK 0x00000004u
#define SDIO_HOST_REGS_STATUS_CMD_TIMEOUT_SHIFT 3u
#define SDIO_HOST_REGS_STATUS_CMD_TIMEOUT_MASK 0x00000008u
#define SDIO_HOST_REGS_STATUS_CMD_CRC_ERR_SHIFT 4u
#define SDIO_HOST_REGS_STATUS_CMD_CRC_ERR_MASK 0x00000010u
#define SDIO_HOST_REGS_STATUS_DAT_CRC_ERR_SHIFT 5u
#define SDIO_HOST_REGS_STATUS_DAT_CRC_ERR_MASK 0x00000020u
#define SDIO_HOST_REGS_STATUS_DAT_TIMEOUT_SHIFT 6u
#define SDIO_HOST_REGS_STATUS_DAT_TIMEOUT_MASK 0x00000040u
#define SDIO_HOST_REGS_STATUS_BUF_ERR_SHIFT 7u
#define SDIO_HOST_REGS_STATUS_BUF_ERR_MASK 0x00000080u
#define SDIO_HOST_REGS_CTRL_OFFSET 0x2Cu   /* RW */
#define SDIO_HOST_REGS_CTRL_RESET 0x00000002u
#define SDIO_HOST_REGS_CTRL_HALF_PERIOD_SHIFT 0u
#define SDIO_HOST_REGS_CTRL_HALF_PERIOD_MASK 0x0000FFFFu
#define SDIO_HOST_REGS_CTRL_BUS4_SHIFT 16u
#define SDIO_HOST_REGS_CTRL_BUS4_MASK 0x00010000u
#define SDIO_HOST_REGS_CTRL_CLK_EN_SHIFT 17u
#define SDIO_HOST_REGS_CTRL_CLK_EN_MASK 0x00020000u
#define SDIO_HOST_REGS_BLKSIZE_OFFSET 0x30u   /* RW */
#define SDIO_HOST_REGS_BLKSIZE_RESET 0x00000200u
#define SDIO_HOST_REGS_TIMEOUT_OFFSET 0x34u   /* RW */
#define SDIO_HOST_REGS_TIMEOUT_RESET 0x000186A0u
#define SDIO_HOST_REGS_IRQ_EN_OFFSET 0x38u   /* RW */
#define SDIO_HOST_REGS_IRQ_EN_RESET 0x00000000u
#endif /* SDIO_HOST_REGS_H */
